"use strict";

var _focusEffect = require("../focusEffect");
describe('focusEffect', function () {
  afterEach(function () {
    (0, _focusEffect.setFocusEffectClass)(null);
  });
  describe('getFocusEffectClass', function () {
    test('should return null by default', function () {
      expect((0, _focusEffect.getFocusEffectClass)()).toBeNull();
    });
    test('should return the class name set by setFocusEffectClass', function () {
      (0, _focusEffect.setFocusEffectClass)('my-focus-class');
      expect((0, _focusEffect.getFocusEffectClass)()).toBe('my-focus-class');
    });
    test('should return updated class after multiple setFocusEffectClass calls', function () {
      (0, _focusEffect.setFocusEffectClass)('first-class');
      (0, _focusEffect.setFocusEffectClass)('second-class');
      expect((0, _focusEffect.getFocusEffectClass)()).toBe('second-class');
    });
  });
  describe('setFocusEffectClass', function () {
    test('should set the focus class', function () {
      (0, _focusEffect.setFocusEffectClass)('custom-class');
      expect((0, _focusEffect.getFocusEffectClass)()).toBe('custom-class');
    });
    test('should clear the focus class when passed null', function () {
      (0, _focusEffect.setFocusEffectClass)('custom-class');
      (0, _focusEffect.setFocusEffectClass)(null);
      expect((0, _focusEffect.getFocusEffectClass)()).toBeNull();
    });
    test('should clear the focus class when passed an empty string', function () {
      (0, _focusEffect.setFocusEffectClass)('custom-class');
      (0, _focusEffect.setFocusEffectClass)('');
      expect((0, _focusEffect.getFocusEffectClass)()).toBeNull();
    });
    test('should support space-separated class names as a single string', function () {
      (0, _focusEffect.setFocusEffectClass)('class-a class-b');
      expect((0, _focusEffect.getFocusEffectClass)()).toBe('class-a class-b');
    });
  });
});